#include "misc.h"
#include "vip.h"
#include "sysreg.h"

# r0 Zero Register
# r1 Reserved for Address Generation
# r2, hsp
# r3, sp
# r4, gp
# r5, tp
# r31, lp
#define ei .hword 0x5800
#define di .hword 0x7800
#define bios_font_gfx gfx10+0x4000

.section .text
.align 1
.balign 1

.global Reset
Reset:
# gp = 0x05008000
movhi 0x501, r0, gp
movea 0x8000, gp, gp

# sp = 0x0500fffc
movhi 0x501, r0, sp
movea 0xfffc, sp, sp

# r8 = 0x02000000
movhi hi(WCR), r0, r8
# r6 = WCR
movea lo(WCR), r8, r6
# WCR = 0
st.b r0, 0[r6]

# wait 0xFFFF steps?
# r1 = 0x00010000
movhi 0x01, r0, r1
# r10 = 0x0000ffff
movea 0xffff, r1, r10
.loop:
# r10 -= 1
add -1, r10
bne .loop


# r8 = 0 fill byte
mov r0, r8
# r1 = 0x00010000 ???
movhi 0x01, r0, r1
# r7 = 0x00008000 bytes
movea 0x8000, r1, r7
# r6 = MAPS
movhi hi(MAPS), r0, r6
jal ClearRam

# r8 = 0 fill byte
mov r0, r8
# r1 = 0x00010000 ???
movhi 0x01, r0, r1
# r7 = 0x00008000 bytes (LFB0 + CTB0)
movea 0x8000, r1, r7
# r6 = LFB0
mov 0, r6
jal ClearRam

# r8 = 0 fill byte
mov r0, r8
# r7 = 0x00004000 bytes
movea 0x4000, r0, r7
# r6 = WRAM
movhi hi(__WRAM_START), r0, r6
jal ClearRam

movhi hi(PostInit), r0, r1
movea lo(PostInit), r1, r1
jmp [r1]

